CREATE TABLE albums(id TEXT PRIMARY KEY,name TEXT,sort_name TEXT,song_count INTEGER,duration INTEGER,size INTEGER,compilation INTEGER,created_at INTEGER,updated_at INTEGER);
CREATE TABLE song_masters(id TEXT PRIMARY KEY,album_id TEXT,title TEXT,duration INTEGER,track INTEGER,disc INTEGER,updated_at INTEGER);
CREATE TABLE song_instances(id TEXT PRIMARY KEY,master_id TEXT,storage_object_id TEXT,source_type TEXT,storage_uri TEXT,suffix TEXT,content_type TEXT,duration INTEGER,size INTEGER,missing INTEGER,tag_scanned INTEGER);
CREATE TABLE storage_objects(id TEXT PRIMARY KEY,physical_key TEXT,suffix TEXT,content_type TEXT,size INTEGER);
CREATE TABLE storage_entries(id TEXT PRIMARY KEY,source_id TEXT,path TEXT,display_name TEXT,kind TEXT,object_id TEXT,instance_id TEXT);
CREATE TABLE album_display_groups(id TEXT PRIMARY KEY,display_name TEXT,sort_name TEXT,created_at INTEGER,updated_at INTEGER);
CREATE TABLE album_display_group_members(group_id TEXT,album_id TEXT,sort_order INTEGER);
WITH RECURSIVE n(x) AS (VALUES(1) UNION ALL SELECT x+1 FROM n WHERE x<555) INSERT INTO song_masters SELECT 'dummy'||x,'pending-uploads','Dummy',CASE WHEN x=1 THEN 223 ELSE 222 END,NULL,NULL,0 FROM n;
WITH RECURSIVE n(x) AS (VALUES(1) UNION ALL SELECT x+1 FROM n WHERE x<555) INSERT INTO song_instances SELECT 'di'||x,'dummy'||x,NULL,'original','r2://dummy','wav','audio/wav',CASE WHEN x=1 THEN 223 ELSE 222 END,CASE WHEN x<=416 THEN 38678296 ELSE 38678295 END,0,1 FROM n;
UPDATE storage_entries SET path='stale-path' WHERE id='se-d122092adcb14fb8b4b75712ab93af81';
